ODD = json.loads("[[\"zero\", {\"error\": [\"ValidationError\", \"TOO-0001: quantity must be positive\"]}], [\"negative_second\", {\"error\": [\"ValidationError\", \"KIT-0001: quantity must be positive\"]}], [\"unknown_sku\", {\"error\": [\"ValidationError\", \"unknown SKU ZZZ-0001\"]}], [\"unknown_sku_zero_qty\", {\"error\": [\"ValidationError\", \"ZZZ-0001: quantity must be positive\"]}], [\"empty\", {\"error\": [\"ValidationError\", \"an order needs at least one line\"]}], [\"custom_price\", {\"ok\": {\"subtotal\": \"59.33\", \"line_discounts\": \"0.00\", \"tier_discount\": \"2.97\", \"coupon_discount\": \"0\", \"taxable\": \"56.36\", \"tax\": \"5.00\", \"shipping\": \"9.99\", \"total\": \"71.35\"}, \"lines\": [[\"TOO-0002\", 2, \"59.33\", \"0.00\", \"59.33\", \"0\"]]}]]")


def check(got_fn, expected):
    try:
        b = got_fn()
    except Exception as e:
        assert 'error' in expected, f'unexpected {type(e).__name__}: {e}'
        assert [type(e).__name__, str(e)] == expected['error']
        return
    assert 'ok' in expected, f"expected {expected.get('error')}"
    assert {k: str(v) for k, v in b.to_dict().items()} == expected['ok']
    assert [[d['sku'], d['quantity'], str(d['gross']), str(d['discount']), str(d['net']), str(d['percent'])]
            for d in b.lines] == expected['lines']


def test_keep_golden_C1():
    from inventory_service.pricing import compute_order_total
    cat, *_ = world()
    for ii, coupon, region, expected in CASES['C1']:
        items = [tuple(x) for x in ITEMS[ii]]
        check(lambda: compute_order_total(lines(cat, *items), cat, customer('C1'), coupon, region), expected)


